import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Go%E3%81%A8WebView.html","title":"GoとWebView","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.64,"words":193},"filePathRelative":"GoとWebView.md"}`),a={name:`GoとWebView.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="goとwebview" tabindex="-1"><a class="header-anchor" href="#goとwebview"><span>GoとWebView</span></a></h1><p>Goで簡単なGUIを作るのにWebViewを使う話。<a href="./Electron代替.html">Electron代替</a></p><ul><li><a href="https://github.com/karino2/mdvcat_go" target="_blank" rel="noopener noreferrer">karino2/mdvcat_go: mdvcat port to go, using webview_go</a> <a href="./mdvcat.html">mdvcat</a>をgoのwebviewに直した。 <ul><li>assetsの例となっている。embed.FSと組み合わせている</li></ul></li></ul><p><a href="./Wails.html">Wails</a>はWebViewモジュールを使っている、という事で簡単なGUIにはWebViewを使うのがいいんじゃないか。</p><h2 id="ハローワールド的な手順" tabindex="-1"><a class="header-anchor" href="#ハローワールド的な手順"><span>ハローワールド的な手順</span></a></h2><p>毎回はじめどうするんだっけ？ってなるので自分的なGetting Startedをここに書いておく。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ mkdir gnewblog</span>
<span class="line">$ cd gnewblog</span>
<span class="line">$ go mod init  github.com/karino2/gnewblog</span>
<span class="line">$ go get github.com/webview/webview_go</span>
<span class="line">$ code main.go</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>でmain.goは以下。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;github.com/webview/webview_go&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	w <span class="token operator">:=</span> webview<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> w<span class="token punctuation">.</span><span class="token function">Destroy</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">SetTitle</span><span class="token punctuation">(</span><span class="token string">&quot;gnewblog&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">SetSize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> webview<span class="token punctuation">.</span>HintNone<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">SetHtml</span><span class="token punctuation">(</span><span class="token string">\`</span>
<span class="line">	&lt;html&gt;</span>
<span class="line">	&lt;body&gt;</span>
<span class="line">		&lt;h1&gt;Hello&lt;/h1&gt;</span>
<span class="line">	&lt;/body&gt;</span>
<span class="line">	&lt;/html&gt;</span>
<span class="line">	\`</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Run</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これでgo run .で立ち上がる。</p><h2 id="テキスト入力のあるダイアログ" tabindex="-1"><a class="header-anchor" href="#テキスト入力のあるダイアログ"><span>テキスト入力のあるダイアログ</span></a></h2><p>RandomThoughtsの一部をコピペしてブログを作りたい時用に、 テキストをコピペしてブログを作るダイアログをコマンドラインから使いたい。</p><p>webviewのBindを使ってイベントを受け取る。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">Ok</span><span class="token punctuation">(</span>basesym <span class="token builtin">string</span><span class="token punctuation">,</span> content <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span>basesym<span class="token punctuation">)</span></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span><span class="token string">&quot;\\n&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span>content<span class="token punctuation">)</span></span>
<span class="line">	os<span class="token punctuation">.</span><span class="token function">Exit</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">Cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	os<span class="token punctuation">.</span><span class="token function">Exit</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>として、webview.Newしたwに対し、</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">	w<span class="token punctuation">.</span><span class="token function">Bind</span><span class="token punctuation">(</span><span class="token string">&quot;Ok&quot;</span><span class="token punctuation">,</span> Ok<span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Bind</span><span class="token punctuation">(</span><span class="token string">&quot;Cancel&quot;</span><span class="token punctuation">,</span> Cancel<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>とする。 こうするとJS側からはapiでawaitで普通に呼べる。</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html"><pre><code class="language-html"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">onCancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">await</span> <span class="token function">Cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>完成品はこちら。</p><p><a href="https://github.com/karino2/gnewblog" target="_blank" rel="noopener noreferrer">karino2/gnewblog: go+webview one-off dialog.</a></p><h3 id="macでのコピペ" tabindex="-1"><a class="header-anchor" href="#macでのコピペ"><span>Macでのコピペ</span></a></h3><p>MacはEditメニューが無いとコピペ出来ない。 どうするの？とchatGPTに聞いたらいい感じのコードを生成してくれた。</p><p><a href="https://github.com/karino2/gnewblog/commit/ffa06144d0d59d1e940ba0ebf0977e09d4f45196" target="_blank" rel="noopener noreferrer">Mac copy-paste support (Add Edit menu) · karino2/gnewblog@ffa0614</a></p><p>こういうのはLLM最強だよな。</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};